CREATE TABLE `outbox_events` (`id` BIGINT NOT NULL AUTO_INCREMENT,`event_id` VARCHAR(36) NOT NULL,`event_type` VARCHAR(120) NOT NULL,`event_version` INTEGER NOT NULL DEFAULT 1,`aggregate_type` VARCHAR(50) NOT NULL,`aggregate_id` INTEGER NOT NULL,`actor_user_id` INTEGER NULL,`correlation_id` VARCHAR(64) NULL,`payload` JSON NOT NULL,`occurred_at` DATETIME(3) NOT NULL,`status` ENUM('PENDING','PROCESSING','DISPATCHED','FAILED') NOT NULL DEFAULT 'PENDING',`dispatch_attempt_count` INTEGER NOT NULL DEFAULT 0,`next_attempt_at` DATETIME(3) NULL,`locked_at` DATETIME(3) NULL,`locked_by` VARCHAR(100) NULL,`delivery_count` INTEGER NOT NULL DEFAULT 0,`dispatched_at` DATETIME(3) NULL,`last_error` TEXT NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE INDEX `uq_outbox_event_id`(`event_id`),INDEX `idx_outbox_due`(`status`,`next_attempt_at`,`created_at`),INDEX `idx_outbox_lock`(`status`,`locked_at`),INDEX `idx_outbox_aggregate`(`aggregate_type`,`aggregate_id`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `notification_deliveries` (`id` BIGINT NOT NULL AUTO_INCREMENT,`event_id` VARCHAR(36) NOT NULL,`recipient_user_id` INTEGER NOT NULL,`channel` ENUM('IN_APP','EMAIL') NOT NULL,`status` ENUM('PENDING','PROCESSING','SENT','FAILED','SKIPPED') NOT NULL DEFAULT 'PENDING',`recipient_address` VARCHAR(255) NULL,`template_code` VARCHAR(100) NOT NULL,`template_version` INTEGER NOT NULL DEFAULT 1,`notification_type` VARCHAR(50) NOT NULL,`title_snapshot` VARCHAR(255) NOT NULL,`text_body_snapshot` TEXT NOT NULL,`html_body_snapshot` LONGTEXT NULL,`related_entity_type` VARCHAR(50) NULL,`related_entity_id` INTEGER NULL,`notification_id` INTEGER NULL,`smtp_message_id` VARCHAR(255) NULL,`provider_message_id` VARCHAR(255) NULL,`attempt_count` INTEGER NOT NULL DEFAULT 0,`next_attempt_at` DATETIME(3) NULL,`locked_at` DATETIME(3) NULL,`locked_by` VARCHAR(100) NULL,`sent_at` DATETIME(3) NULL,`skipped_at` DATETIME(3) NULL,`skip_reason` VARCHAR(100) NULL,`last_error` TEXT NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE INDEX `uq_delivery_event_recipient_channel`(`event_id`,`recipient_user_id`,`channel`),UNIQUE INDEX `uq_delivery_notification`(`notification_id`),INDEX `idx_delivery_due`(`status`,`next_attempt_at`,`created_at`),INDEX `idx_delivery_lock`(`status`,`locked_at`),INDEX `idx_delivery_recipient_channel_status`(`recipient_user_id`,`channel`,`status`),PRIMARY KEY (`id`),CONSTRAINT `fk_delivery_user` FOREIGN KEY (`recipient_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,CONSTRAINT `fk_delivery_notification` FOREIGN KEY (`notification_id`) REFERENCES `notifications`(`id`) ON DELETE SET NULL ON UPDATE RESTRICT) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
